fn shell_game(n: i32, x: i8) -> i8 {
    // The sequence of swaps generates permutations in S₃ with period 6,
    // since (q ∘ p)^3 = identity, where
    // p = swap(0,1) and q = swap(1,2).
    // So we only need n mod 6.
    let m = n.rem_euclid(6);
    match m {
        0 => x, // identity
        1 => match x { // p = swap(0,1)
            0 => 1,
            1 => 0,
            2 => 2,
            _ => unreachable!(),
        },
        2 => match x { // q ∘ p = (0 → 2 → 1 → 0)
            0 => 2,
            1 => 0,
            2 => 1,
            _ => unreachable!(),
        },
        3 => match x { // p ∘ q ∘ p
            0 => 2,
            1 => 1,
            2 => 0,
            _ => unreachable!(),
        },
        4 => match x { // q ∘ p ∘ q ∘ p
            0 => 1,
            1 => 2,
            2 => 0,
            _ => unreachable!(),
        },
        5 => match x { // p ∘ q ∘ p ∘ q ∘ p
            0 => 0,
            1 => 2,
            2 => 1,
            _ => unreachable!(),
        },
        _ => unreachable!(),
    }
}

#[cfg(test)]
mod tests {
    use super::shell_game;

    #[test]
    fn test_small() {
        // brute‐force for n up to, say, 10
        for n in 0..10 {
            for x in 0..3 {
                // simulate directly
                let mut pos = x;
                for i in 1..=n {
                    if i % 2 != 0 {
                        // odd: swap 0<->1
                        pos = match pos {
                            0 => 1,
                            1 => 0,
                            2 => 2,
                            _ => pos,
                        };
                    } else {
                        // even: swap 1<->2
                        pos = match pos {
                            1 => 2,
                            2 => 1,
                            0 => 0,
                            _ => pos,
                        };
                    }
                }
                assert_eq!(shell_game(n, x), pos);
            }
        }
    }
}